import{z as E,x as p,o as r,c as d,q as s,j as o,D as e,d as n,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"GFS / HDFS","description":"","frontmatter":{"title":"GFS / HDFS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gfs-hdfs.md","filePath":"cs/gfs-hdfs.md","lastUpdated":1791413859000}'),A={name:"cs/gfs-hdfs.md"};function B(h,a,c,S,m,f){const t=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="gfs-hdfs" tabindex="-1">GFS / HDFS <a class="header-anchor" href="#gfs-hdfs" aria-label="Permalink to &quot;GFS / HDFS&quot;">​</a></h1><div class="epigraph"><p>大文件切块，多副本放块服务器；主存元数据。主是 CP 小状态，数据面是尽力吞吐。客户端缓存块位置，租约管写。</p><footer>—— 据 Ghemawat, Gobioff and Leung, The Google File System, SOSP 2003；HDFS 架构（Shvachko et al., MSST 2010）整理</footer></div><p>上一课<a href="/cs/chaos-engineering">混沌</a>把崩溃当实验。GFS 把崩溃当<strong>日常设计点</strong>。缺口是<strong>大数据文件如何在普通机器上活</strong>：不是 etcd 里放 blob。本课钉主 + 块副本。后课对象存储换 API 与一致性档。不重写 Raft 日志。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GFS：chunk 默认 64MB，三副本。Master 管命名空间与块位置，不承运数据。客户端问主拿位置，再打 chunkserver。写：主发租约给主副本，流水线推数据，主副本排序，再数据推。主故障：有 checkpoint+操作日志，早期单主切换慢——这是<a href="/cs/primary-backup-failover">主备</a>形态。</p><p>HDFS 公开实现同族：NameNode + DataNode，块报告、租约、流水线。HA NameNode 后来用共享编辑日志或独立 Journal。</p><p><span class="marginnote">SOSP 2003 强调弱一致性：追加、快照、主缓存过期。MapReduce 的输入是这种文件。本课不写 MapReduce。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：从最近副本读，校验和。写：租约防双写同一 chunk。主内存元数据要匹配块服务器心跳；幽灵块靠校验与扫描。</p>',9)),(r(),o(l,null,{default:e(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20M%5B%22%E4%B8%BB%20%2F%20NameNode%22%5D%0A%20%20M%20--%3E%20LOC%5B%22%E5%9D%97%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20C%20--%3E%20CS%5B%22chunkserver%20%2F%20DataNode%22%5D%0A%20%20CS%20--%3E%20REP%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p>不要把主当数据面：主过载会让整个命名空间停，尽管磁盘还在。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一致性：GFS 对并发写不保证 POSIX 全语义，保证追加的「至少一次」类记录追加（record append）可能有填充与重复——应用要容。这与<a href="/cs/linearizability">线性一致</a>文件对象不同。HDFS 对打开写的文件限制更严。选档为吞吐。</p><p><span class="marginnote">数字实例：chunk 取 64MB 是为了把元数据压到主能全放内存——1 PB 数据 ÷ 64MB ≈ 1600 万个块，主用不到几 GB 内存就能记住所有位置。若块只有 4KB，同样 1 PB 就是 2.7 亿个块，主内存与心跳报告都会爆炸。大块还让客户端长时间打同一台 chunkserver，减少元数据请求次数。</span></p><p><span class="marginnote">术语翻译：租约（lease）就是「有时限的写授权」——主把某一块的 primary 身份发给一个副本，说「在接下来 60 秒内由你决定写顺序」。租约到期作废，主就能安全地把角色另授他人；双主不会同时有效，因为旧租约一定先过期。</span></p>',5)),(r(),o(l,null,{default:e(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%86%99%2064MB%20%E5%9D%97%22%5D%20--%3E%20P%5B%22primary%20%E5%89%AF%E6%9C%AC%E6%8C%81%E7%A7%9F%E7%BA%A6%E5%AE%9A%E5%BA%8F%22%5D%0A%20%20P%20--%3E%20S1%5B%22%E5%89%AF%E6%9C%AC%202%20%E6%B5%81%E6%B0%B4%E7%BA%BF%E6%8E%A5%E6%94%B6%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%89%AF%E6%9C%AC%203%20%E6%B5%81%E6%B0%B4%E7%BA%BF%E6%8E%A5%E6%94%B6%22%5D%0A%20%20S2%20--%3E%20ACK%5B%22%E5%90%84%E5%89%AF%E6%9C%AC%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20ACK%20--%3E%20COM%5B%22primary%20%E5%9B%9E%E5%AE%A2%E6%88%B7%E7%AB%AF%20%E8%BF%BD%E5%8A%A0%E8%87%B3%E5%B0%91%E4%B8%80%E6%AC%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>与 Chubby：GFS 主选主可外包锁服务。与<a href="/cs/chain-replication">链式复制</a>：流水线像短链，提交规则是租约主排序。</p><p><span class="marginnote">常见误区：初学者容易以为 record append「至少一次」等于「正好一次」，于是并发追加不会重。实际上某副本超时未确认时，primary 会令整个追加重试，成功副本上就出现重复记录，中间还可能被填充凑齐对齐——所以读取端要靠记录内的校验和与唯一 ID 去重。</span></p><p>本课不写纠删码替代三副本的全部。也不写小文件海量的 NameNode 内存墙——下一课元数据会碰。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Colossus 内部当公开规格。后课默认：块存储 = 小 CP 元数据 + 大数据面副本；POSIX 语义不默认。对象存储下一课把命名空间再摊平。分布式文件元数据课专门打 NameNode 墙。</p><p>数据面可丢一台；元数据面是控制面单点，必须有自己的恢复故事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GFS/HDFS：主管元数据，块服务器管字节，租约管写。</li><li>文件语义弱于 POSIX；为吞吐与追加。</li><li>主必须快照+日志；客户端缓存位置会过期。</li><li>出处：Ghemawat et al., SOSP 2003；Shvachko et al., MSST 2010。</li></ul>',8))])}const D=E(A,[["render",B]]);export{u as __pageData,D as default};
